// This file is part of Moodle - https://moodle.org/

/**
 * Download proxy for temporary study sheet PDFs generated by /notes.
 *
 * The browser calls this page; it fetches the file from the backend with the plugin's
 * API key. The backend URL and key never reach the browser, and the user id sent to
 * the backend is always the logged-in user's, so students cannot fetch each other's
 * files. The PDF is streamed straight through and never stored in Moodle.
 *
 * Responses: 200 PDF bytes; otherwise JSON {"error": code, "message": text} with
 * 403 forbidden, 400 invalid, 404 notfound, 410 expired or 502 unavailable.
 *
 * @package local_ragassistant
 */

require_once(__DIR__ . '/../../config.php');

use local_ragassistant\local\course_policy;

/**
 * Send a JSON error the chat JavaScript can show, and stop.
 *
 * @param int $status HTTP status code.
 * @param string $code Short machine-readable code.
 * @param string $stringid Language string with the message for the student.
 */
function local_ragassistant_download_error(int $status, string $code, string $stringid): void {
    http_response_code($status);
    header('Content-Type: application/json; charset=utf-8');
    header('Cache-Control: private, no-store');
    echo json_encode([
        'error' => $code,
        'message' => get_string($stringid, 'local_ragassistant'),
    ]);
    exit;
}

$courseid = required_param('courseid', PARAM_INT);
$course = get_course($courseid);
require_login($course);
require_sesskey();
$context = context_course::instance($course->id);

// Same rule as the chat page itself: a user who may not chat here gets nothing.
if (!course_policy::can_use_chat($courseid, $context)) {
    local_ragassistant_download_error(403, 'forbidden', 'chatnopermission');
}

$fileid = required_param('id', PARAM_ALPHANUM);
if (!preg_match('/^[0-9a-f]{32}$/', $fileid)) {
    local_ragassistant_download_error(400, 'invalid', 'downloadexpired');
}

// Release the session lock while waiting on the backend.
\core\session\manager::write_close();

try {
    // user_id is always the logged-in user, never a request parameter.
    $file = (new \local_ragassistant\local\api_client())
        ->get_generated_file($fileid, (int) $course->id, (int) $USER->id);
} catch (\Throwable $exception) {
    // Log only the reason, never the backend URL, key or file contents.
    // phpcs:ignore moodle.PHP.ForbiddenFunctions.FoundWithAlternative
    error_log('local_ragassistant: study sheet download failed: ' . get_class($exception));
    local_ragassistant_download_error(502, 'unavailable', 'downloadunavailable');
}

if ($file['status'] === 404) {
    local_ragassistant_download_error(404, 'notfound', 'downloadexpired');
}
if ($file['status'] === 410) {
    local_ragassistant_download_error(410, 'expired', 'downloadexpired');
}
if ($file['status'] !== 200 || $file['contenttype'] !== 'application/pdf' || $file['body'] === '') {
    // phpcs:ignore moodle.PHP.ForbiddenFunctions.FoundWithAlternative
    error_log('local_ragassistant: study sheet download returned HTTP ' . $file['status']);
    local_ragassistant_download_error(502, 'unavailable', 'downloadunavailable');
}

// Sanitise the backend's filename and make sure it ends in .pdf.
$filename = clean_filename($file['filename']);
if ($filename === '' || $filename === '.pdf') {
    $filename = 'study_sheet.pdf';
}
if (core_text::strtolower(substr($filename, -4)) !== '.pdf') {
    $filename .= '.pdf';
}
$asciiname = preg_replace('/[^A-Za-z0-9._-]/', '_', $filename);

header('Content-Type: application/pdf');
header('Content-Disposition: attachment; filename="' . $asciiname . '"; filename*=UTF-8\'\'' .
    rawurlencode($filename));
header('Content-Length: ' . strlen($file['body']));
header('Cache-Control: private, no-store');
header('X-Content-Type-Options: nosniff');
echo $file['body'];
exit;
